using System;
using UnityEngine;
using UnityEngine.UI;

// First-play, account-scoped explanations. Reading a guide never starts a timer or earns a play badge.
public sealed class FocusHowTo : MonoBehaviour {
 public sealed class Page {public string Title,Body;public int Demo;public Page(string title,string body,int demo){Title=title;Body=body;Demo=demo;}}
 public static Page[] Pages(int kind){
  if(kind==0)return new[]{new Page("Solve the calculation","Enter your answer on the keypad.\nTap OK to submit. Clear removes your answer.",0),new Page("Four operations","Levels introduce addition, subtraction,\nmultiplication and division.\nThe answer is always a whole number.",1),new Page("Beat the clock","You have 90 seconds. Each correct answer gives +1.\nFinish a set to advance. Errors do not remove points.\nChoose a starting level with + or − before START.",2)};
  if(kind==1)return new[]{new Page("Catch before impact","Watch the RED ball. Tap the wall it is heading\ntowards BEFORE it reaches that wall.\nYou can also tap the white area nearest that wall.",3),new Page("Green means saved","A correct tap turns the ball GREEN: +1 point.\nIt is safe until the next bounce.\nA bounce you did not save costs 1 point.",4),new Page("More to watch","Higher levels add balls and boxes.\nEach box has its own touch area.\nSave every target to advance. You have 90 seconds.",5)};
  if(kind==2)return new[]{new Page("Watch, then remember","The numbers appear in circles, then disappear.\nRemember their positions and tap in the correct order.\n3 numbers: 1 second. 4–6: 2 seconds. 7+: 3 seconds.",6),new Page("Green goes up","Tap the GREEN numbers from smallest to largest.\nFor example: 1, then 2, then 3.",7),new Page("Red goes down","Tap the RED numbers from largest to smallest.\nFor example: 3, then 2, then 1.",8),new Page("Alternate colours","Take one GREEN, then one RED.\nGreen goes up; red goes down.\nRepeat until every number is gone.",9),new Page("Three parts per level","Every level has green, red, then mixed.\nComplete all three to advance. There are 12 levels.\nYou have 90 seconds; each correct tap gives +1.",2)};
  return new[]{new Page("Green goes up","The numbers stay visible in Chain.\nTap GREEN numbers from smallest to largest.\nExample: 1, then 2, then 3.",7),new Page("Red goes down","Tap RED numbers from largest to smallest.\nExample: 3, then 2, then 1.",8),new Page("Green first, then red","When the rule says GREEN FIRST, finish all green\nnumbers upwards, then all red numbers downwards.\nExample: green 1, 2, 3; then red 3, 2, 1.",10),new Page("Alternate colours","When the rule says ALTERNATE, switch colour\nafter every tap. Green goes up; red goes down.\nRepeat until every number is gone.",9),new Page("Follow the rule","Read the rule above the board: it changes by level.\nComplete the sequence to advance.\n90 seconds; +1 per correct tap. Numbers stay visible.",2)};
 }
 static string Key(int owner,int kind){return "focus.howto.v1."+owner+"."+kind;}
 public static bool Needed(int owner,int kind){return PlayerPrefs.GetInt(Key(owner,kind),0)==0;}
 static Sprite guideFrame;int owner,kind,index;float exampleStarted;Page[] pages;Action done;GameObject popup,demo;Transform content;Text title,body,progress;Button back,next;
 public static FocusHowTo Open(Transform parent,int owner,int kind,Action done){var old=parent.GetComponentInChildren<FocusHowTo>(true);if(old!=null)return old;var host=new GameObject("Focus how to",typeof(RectTransform),typeof(FocusHowTo));host.transform.SetParent(parent,false);var rect=(RectTransform)host.transform;rect.anchorMin=Vector2.zero;rect.anchorMax=Vector2.one;rect.offsetMin=rect.offsetMax=Vector2.zero;var guide=host.GetComponent<FocusHowTo>();guide.owner=owner;guide.kind=kind;guide.done=done;guide.pages=Pages(kind);guide.Build();return guide;}
 void Build(){
  popup=Instantiate(Resources.Load<GameObject>("Prefabs/GamePopUps/MidGameQuitPanel"),transform,false);content=popup.transform.GetChild(0);var rect=(RectTransform)content;rect.anchorMin=new Vector2(.07f,.16f);rect.anchorMax=new Vector2(.93f,.84f);rect.offsetMin=rect.offsetMax=Vector2.zero;rect.localScale=Vector3.one;content.GetComponent<Image>().preserveAspect=false;
  // Slice the original popup artwork instead of stretching its corner pixels on a tall page.
  var frame=content.GetComponent<Image>();if(guideFrame==null){var source=frame.sprite;float edge=Mathf.Min(source.rect.width,source.rect.height)*.25f;guideFrame=Sprite.Create(source.texture,source.rect,new Vector2(.5f,.5f),source.pixelsPerUnit,0,SpriteMeshType.FullRect,new Vector4(edge,edge,edge,edge));guideFrame.hideFlags=HideFlags.HideAndDontSave;}frame.sprite=guideFrame;frame.type=Image.Type.Sliced;frame.pixelsPerUnitMultiplier=4;
  back=content.GetChild(2).GetComponent<Button>();next=content.GetChild(3).GetComponent<Button>();foreach(var text in content.GetComponentsInChildren<Text>(true))if(!text.transform.IsChildOf(back.transform)&&!text.transform.IsChildOf(next.transform))text.gameObject.SetActive(false);
  Position((RectTransform)back.transform,new Vector2(.07f,.06f),new Vector2(.47f,.17f));Position((RectTransform)next.transform,new Vector2(.53f,.06f),new Vector2(.93f,.17f));foreach(var button in new[]{back,next}){var label=button.GetComponentInChildren<Text>();Position(label.rectTransform,new Vector2(.04f,.08f),new Vector2(.96f,.92f));label.resizeTextForBestFit=true;label.resizeTextMinSize=18;label.resizeTextMaxSize=40;}back.onClick=new Button.ButtonClickedEvent();next.onClick=new Button.ButtonClickedEvent();back.onClick.AddListener(Back);next.onClick.AddListener(Next);
  title=Text(content,"",new Vector2(.06f,.78f),new Vector2(.94f,.94f),37);title.fontStyle=FontStyle.Bold;title.color=FocusGame.Teal;
  body=Text(content,"",new Vector2(.06f,.28f),new Vector2(.94f,.53f),26);progress=Text(content,"",new Vector2(.08f,.19f),new Vector2(.92f,.26f),20);ShowPage();
 }
 static void Position(RectTransform rect,Vector2 min,Vector2 max){rect.anchorMin=min;rect.anchorMax=max;rect.offsetMin=rect.offsetMax=Vector2.zero;}
 static Text Text(Transform parent,string value,Vector2 min,Vector2 max,int size){var text=ChainGame.Label(parent,value,min,max,size,ChainGame.Ink);text.resizeTextForBestFit=true;text.resizeTextMinSize=18;text.resizeTextMaxSize=size;text.raycastTarget=false;return text;}
 void ShowPage(){
  title.text=FocusRules.Names[kind]+" · "+pages[index].Title;body.text=MemorySettings.Practice?pages[index].Body.Replace("You have 90 seconds.","Practice has no time limit.").Replace("You have 90 seconds","Practice has no time limit").Replace("90 seconds;","No time limit;").Replace("90 seconds","No time limit"):pages[index].Body;progress.text=(index+1)+" / "+pages.Length;back.GetComponentInChildren<Text>().text=index==0?"Close":"Back";next.GetComponentInChildren<Text>().text=index==pages.Length-1?(done==null?"Done":"Play"):"Next";
  if(demo!=null){demo.SetActive(false);CardFaces.DestroyGenerated(demo);}demo=ChainGame.Panel(content,"Example",new Vector2(.07f,.54f),new Vector2(.93f,.77f),Color.clear);Canvas.ForceUpdateCanvases();Draw(pages[index].Demo);exampleStarted=Time.unscaledTime;
 }
 void Draw(int type){
  if(type==0||type==1){Text(demo.transform,type==0?"7 + 5 = 12":"+     −     ×     ÷",Vector2.zero,Vector2.one,52).color=FocusGame.Teal;return;}
  if(type==2){Text(demo.transform,MemorySettings.Practice?"∞":"90",new Vector2(.1f,.1f),new Vector2(.9f,.9f),78).color=FocusGame.Teal;return;}
  if(type>=3&&type<=5){int count=type==5?3:1;for(int n=0;n<count;n++){var box=ChainGame.Panel(demo.transform,"Actual wall style",new Vector2(n/(float)count+.03f,.1f),new Vector2((n+1)/(float)count-.03f,.9f),new Color32(192,215,217,255));ChainGame.Panel(box.transform,"White play area",new Vector2(.05f,.05f),new Vector2(.95f,.95f),Color.white);var ball=ChainGame.Panel(box.transform,"Ball",new Vector2(.6f,.5f),new Vector2(.6f,.5f),type==4?FocusGame.Green:FocusGame.Red).GetComponent<Image>();ball.sprite=FocusGame.Circle;ball.rectTransform.sizeDelta=new Vector2(28,28);if(type==4)ChainGame.Panel(box.transform,"Saved wall",new Vector2(.95f,0),Vector2.one,FocusGame.Green);else Text(box.transform,"→",new Vector2(.7f,.25f),new Vector2(.95f,.75f),38).color=FocusGame.Red;}return;}
  int[] keys=type==8?new[]{1003,1002,1001}:type==9?new[]{1,1003,2,1002,3,1001}:type==10?new[]{1,2,3,1003,1002,1001}:new[]{1,2,3};float width=((RectTransform)demo.transform).rect.width;float diameter=Mathf.Min(82,width/(keys.Length+1)*.83f);
  for(int n=0;n<keys.Length;n++){var button=FocusGame.NumberToken(demo.transform,keys[n],new Vector2((n+1f)/(keys.Length+1),.5f),diameter,kind==2);button.interactable=false;}
 }
 void Update(){if(demo==null||pages[index].Demo!=6)return;bool visible=(Time.unscaledTime-exampleStarted)%3<1;foreach(var button in demo.GetComponentsInChildren<Button>()){int key=int.Parse(button.name.Substring("Token ".Length));button.GetComponentInChildren<Text>().text=visible?(key%1000).ToString():"";}}
 public void Back(){if(index==0){Close();return;}index--;ShowPage();}
 public void Next(){if(index<pages.Length-1){index++;ShowPage();return;}if(owner!=GameManager.AchievementUserId){Close();return;}PlayerPrefs.SetInt(Key(owner,kind),1);PlayerPrefs.Save();var callback=done;Close();if(callback!=null)callback();}
 public void Close(){gameObject.SetActive(false);CardFaces.DestroyGenerated(gameObject);}
}
